package org.thesis.eval;
import com.github.javaparser.ast.*;import com.github.javaparser.ast.body.*;import com.github.javaparser.ast.expr.*;import java.util.*;
final class Lcom4 {
 static Models.LcomResult calculate(SourceIndex idx,Models.ManifestRow mr)throws Exception{Models.LcomResult r=new Models.LcomResult();r.method=mr;MethodDeclaration target=RepositoryTargetLocator.findRepo(idx,mr);if(target==null){r.lcom4=Double.NaN;r.notes.add("target not found");return r;}TypeDeclaration<?> td=target.findAncestor(TypeDeclaration.class).orElse(null);if(td==null){r.lcom4=Double.NaN;return r;}r.classFqn=idx.fqnFor(td);List<MethodDeclaration> ms=new ArrayList<>(td.getMethods());r.methodCount=ms.size();if(ms.isEmpty()){r.components=0;r.lcom4=0;return r;}int n=ms.size();boolean[][] edge=new boolean[n][n];List<Set<String>> fields=new ArrayList<>();for(MethodDeclaration m:ms){Set<String> f=new HashSet<>();for(NameExpr ne:m.findAll(NameExpr.class)){idx.field(r.classFqn,ne.getNameAsString()).ifPresent(x->f.add(ne.getNameAsString()));}for(FieldAccessExpr fa:m.findAll(FieldAccessExpr.class))if(fa.getScope().isThisExpr())f.add(fa.getNameAsString());fields.add(f);}for(int i=0;i<n;i++)for(int j=i+1;j<n;j++){Set<String>x=new HashSet<>(fields.get(i));x.retainAll(fields.get(j));if(!x.isEmpty())edge[i][j]=edge[j][i]=true;}Map<String,List<Integer>> byName=new HashMap<>();for(int i=0;i<n;i++)byName.computeIfAbsent(ms.get(i).getNameAsString(),k->new ArrayList<>()).add(i);for(int i=0;i<n;i++)for(MethodCallExpr c:ms.get(i).findAll(MethodCallExpr.class)){boolean same=c.getScope().isEmpty()||c.getScope().get().isThisExpr();if(same)for(int j:byName.getOrDefault(c.getNameAsString(),List.of()))edge[i][j]=edge[j][i]=true;}boolean[] seen=new boolean[n];int comp=0;for(int i=0;i<n;i++)if(!seen[i]){comp++;Deque<Integer>q=new ArrayDeque<>();q.add(i);seen[i]=true;while(!q.isEmpty()){int u=q.remove();for(int v=0;v<n;v++)if(edge[u][v]&&!seen[v]){seen[v]=true;q.add(v);}}}r.components=comp;r.lcom4=comp;r.notes.add("LCOM4 = connected components of declaring-class methods; edges are same-class calls or shared field access; constructors excluded.");return r;}
}
